"""Purchase workspace presentation, reusing existing fields and server actions."""
CSS = '''
.po-intro{margin:0 0 20px}.po-eyebrow{font-size:12px;font-weight:800;letter-spacing:.08em;color:#42627d}.po-intro h2{font-size:27px;margin:8px 0}.po-intro p{line-height:1.5}.po-nav{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}.po-nav a{padding:10px 14px;border:1px solid #afc5df;border-radius:8px;background:#fff;color:#15396d;text-decoration:none;font-weight:650}.po-workspace{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(320px,.85fr);gap:22px;align-items:start}.po-workspace>div,.po-workspace>aside{min-width:0}.po-workspace .card{margin:0 0 18px}.po-step{border:1px solid #b5c9df!important;border-top:4px solid #6c93bd!important;background:#f2f7ff!important;padding:22px!important;border-radius:12px}.po-step.po-conditions{background:#f0f8f5!important;border-top-color:#4e9082!important}.po-step.po-payments{background:#fff9ee!important;border-top-color:#be944c!important}.po-step.po-save{background:#f5f1fa!important;border-top-color:#9480b5!important}.po-heading{display:flex;gap:14px;align-items:flex-start;margin-bottom:20px}.po-heading>span{background:#214b7c;color:#fff;border-radius:9px;min-width:36px;height:36px;display:grid;place-items:center;font-size:21px;font-weight:750}.po-heading h2{font-size:19px;margin:0 0 5px!important}.po-heading p{margin:0;line-height:1.5;color:#42627d;font-size:15px}.po-workspace [hidden]{display:none!important}.po-workspace label{display:flex;flex-direction:column;min-width:0;font-size:14px;line-height:1.5;margin-bottom:14px}.po-workspace input:not([type=checkbox]),.po-workspace select{box-sizing:border-box;width:100%;min-height:43px;font:inherit;padding:10px;border:1px solid #a8bfdc;border-radius:7px;background:white;margin-top:6px}.po-workspace input[readonly]{background:#edf3fb;color:#38577a}.po-workspace .fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;align-items:start}.po-workspace button,#po-saved button,#review-panel button{padding:11px 16px;border:1px solid #adc6e7;border-radius:7px;background:#edf4ff;color:#173e76;font-weight:650;cursor:pointer;margin:5px 8px 5px 0;line-height:1.4}.po-workspace button.primary{background:#183e78;color:#fff;border-color:#183e78}.po-workspace button:disabled{opacity:.55;cursor:default}.po-subsection{border:1px solid #c3d0df;border-radius:9px;background:#fff;padding:17px;margin:16px 0}.po-subsection>h3{font-size:16px;margin:0 0 14px}.po-workspace small{display:block;font-size:13px;line-height:1.5;color:#4c627b;margin:5px 0 12px}.po-workspace label:has(input[type=checkbox]){display:block}.po-workspace .metric{background:#eaf2fd;border:1px solid #cfdded;padding:14px;border-radius:8px;min-width:0}.po-workspace .metric strong{font-size:19px;line-height:1.4;overflow-wrap:anywhere}.po-workspace details{margin:15px 0}.po-workspace summary{font-weight:700;cursor:pointer;line-height:1.5}.po-totals{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:12px 0}.po-total{border:1px solid #b8d2cb;border-radius:8px;padding:12px;background:#f0f8f5}.po-total span{font-size:13px;color:#42627d;display:block}.po-total strong{font-size:20px;display:block;margin-top:6px}.po-total.po-grand{grid-column:1/-1;background:#e5efff;border:2px solid #638bbc}.po-source{padding:12px 15px;background:#eaf2fd;border:1px solid #b9cce6;border-radius:8px;line-height:1.5;margin-bottom:18px}.po-comparison{padding:14px;background:#fff3d8;border-left:5px solid #b98527;line-height:1.5;border-radius:6px}.po-workspace #proposal-cost-summary{font-size:14px;line-height:1.5}.po-context .scroll{overflow:auto}.po-save .actions{display:block}.po-notice{font-weight:650;line-height:1.5}.po-workspace .files-subpanel{padding:12px;background:#f7faff}.po-saved{margin-top:24px}#review-panel{border:2px solid #c99b4f;border-radius:12px;margin-top:24px}#review-panel .review-header{padding:22px}#review-panel .review-header h2{font-size:24px;line-height:1.3}
@media(max-width:1100px){.po-workspace{grid-template-columns:minmax(0,1fr)}.po-context{position:static}}@media(max-width:580px){.po-workspace .fields,.po-totals{grid-template-columns:minmax(0,1fr)}.po-step{padding:16px!important}.po-total.po-grand{grid-column:auto}.po-nav a{flex:1 1 40%;text-align:center}}
'''

JS = r'''
(function buildPurchaseWorkspace(){
 const form=$('form'),page=form.closest('[data-view]'),cards=Array.from(form.querySelectorAll('section.card'));
 const article=cards.find(c=>c.querySelector('#article')),supplier=cards.find(c=>c.querySelector('#supplier')),context=cards.find(c=>c.querySelector('#last-price')),proposal=cards.find(c=>c.querySelector('#proposal-cost-summary')),actions=form.querySelector('.actions'),saved=page.querySelector('#rows').closest('section');
 const intro=document.createElement('header');intro.className='po-intro';intro.innerHTML='<p class="po-eyebrow">ÁREA DE COMPRAS</p><h2>Prepara y revisa tu propuesta de compra</h2><p>Consulta las referencias, negocia con el proveedor y revisa el efecto previsto sobre la empresa.</p><nav class="po-nav" aria-label="Pasos de la propuesta de compra"><a href="#po-selection">1 · Proveedor y artículo</a><a href="#po-conditions">2 · Precio y cantidad</a><a href="#po-payments">3 · Pagos y portes</a><a href="#po-save">4 · Guardar y revisar</a></nav>';
 const source=document.createElement('p');source.id='po-source';source.className='po-source';source.setAttribute('role','status');page.prepend(intro,source);
 const workspace=document.createElement('div');workspace.className='po-workspace';const editor=document.createElement('div'),aside=document.createElement('aside');aside.className='po-context';aside.setAttribute('aria-label','Ficha e historial de compra');workspace.append(editor,aside);form.append(workspace);
 function step(id,n,title,help,extra=''){const box=document.createElement('section');box.id=id;box.className='card po-step '+extra;const heading=document.createElement('div');heading.className='po-heading';const number=document.createElement('span');number.textContent=n;const text=document.createElement('div'),h=document.createElement('h2'),p=document.createElement('p');h.textContent=title;p.textContent=help;text.append(h,p);heading.append(number,text);box.append(heading);editor.append(box);return box}
 function group(parent,title){const box=document.createElement('section');box.className='po-subsection';const h=document.createElement('h3');h.textContent=title;box.append(h);parent.append(box);return box}
 function field(name){return form.elements[name].closest('label')}
 const selection=step('po-selection','1','PROVEEDOR Y ARTÍCULO','Elige primero el proveedor y después busca el producto entre sus referencias.');
 supplier.querySelector('h2').textContent='Proveedor de la propuesta';selection.append(supplier);supplier.className='po-subsection';
 const placeholders=supplier.querySelector('.fields');placeholders.replaceChildren();const locality=document.createElement('p');locality.id='po-supplier-detail';placeholders.append(locality);
 const picker=group(selection,'Seleccionar artículo');const search=article.querySelector('#purchase-article-query').closest('.files-subpanel');picker.append(search,field('article_id'));
 article.querySelector('h2').textContent='FICHA DEL ARTÍCULO';aside.append(article,context);context.querySelector('h2').textContent='REFERENCIAS PARA NEGOCIAR';context.classList.add('po-reference-card');
 const conditions=step('po-conditions','2','CONDICIONES QUE SE PROPONEN','Introduce la oferta del proveedor. Los importes se actualizan con los descuentos e impuestos declarados.','po-conditions');
 conditions.append(field('pricing_mode'));const pricing=group(conditions,'Precio y cantidad');const pricingNote=$('proposal-discount-fields').nextElementSibling;pricing.append(form.elements.unit_price.closest('.fields'),$('proposal-discount-fields'));if(pricingNote?.tagName==='SMALL')pricing.append(pricingNote);
 pricing.append(field('vat_percent'));const totals=document.createElement('div');totals.id='po-totals';totals.className='po-totals';totals.setAttribute('role','status');conditions.append(totals,$('proposal-cost-summary'));const compare=$('comparison');compare.classList.add('po-comparison');conditions.append(compare);
 const payments=step('po-payments','3','PAGOS, PORTES Y ENTREGA','Distingue cuándo se paga la mercancía y quién asume el transporte. No se deducen pagos ni portes desconocidos.','po-payments');
 const dates=group(payments,'Fechas y lugar de entrega'),dateFields=document.createElement('div');dateFields.className='fields';dateFields.append(field('order_date'),field('due_date'));dates.append(dateFields,field('delivery_location'),$('proposal-delivery-source'));
 const freight=group(payments,'Portes de la compra');freight.append(field('shipping_mode'),$('proposal-shipping-fields'),$('proposal-shipping-note'));payments.append($('proposal-payment-plan'));
 const completion=step('po-save','4','GUARDAR Y REVISAR LA PROPUESTA','Guardar abre la revisión del precio, stock y situación financiera. No confirma un pedido ni autoriza la compra.','po-save');completion.append(field('reference'));const refs=proposal.querySelector('details');if(refs)completion.append(refs);completion.append(actions);$('save').textContent='Guardar propuesta y abrir revisión';const notice=document.createElement('p');notice.id='po-notice';notice.className='po-notice';notice.setAttribute('role','status');completion.append(notice);
 const remaining=Array.from(proposal.children).filter(n=>n.tagName!=='H2'&&(n.querySelector('input,select,textarea')||n.id));remaining.forEach(n=>completion.append(n));form.replaceChildren(workspace);saved.id='po-saved';saved.classList.add('po-saved');page.append($('review-panel'),saved);
 intro.querySelectorAll('a').forEach(a=>a.onclick=event=>{event.preventDefault();const target=$(a.hash.slice(1));target.scrollIntoView({behavior:'smooth',block:'start'});target.setAttribute('tabindex','-1');target.focus({preventScroll:true})});
 function render(){if(!state)return;const info=state.info,book=info.exclusive_workbook;source.textContent='Empresa: '+(info.company.legal_name||info.company.company_id)+' · Archivo: '+(book?.filename||'Expediente documental base')+' · Corte: '+stockDate(info.as_of_date);const s=state.suppliers.find(x=>x.supplier_id===$('supplier').value);locality.textContent='Contacto: '+(s?.contact_name||s?.contact_person||'Sin dato documentado')+' · Localidad: '+(s?.locality||'Sin dato documentado');totals.replaceChildren();const q=commercialQuote,t=q?.commercial_terms;for(const [label,value,grand] of [['Antes de descuentos',q?money(t.gross_line)+' EUR':'Pendiente',false],['Descuento de mercancía',q?money(t.discount_amount)+' EUR':'Pendiente',false],['Mercancía neta',q?money(q.net)+' EUR':'Pendiente',false],['IVA mercancía',q?money(q.tax)+' EUR':'Pendiente',false],['Portes con IVA',q&&t.shipping?.total!==null&&t.shipping?.total!==undefined?money(t.shipping.total)+' EUR':'Pendiente de confirmar',false],['Total previsto a pagar',q&&q.operation_total!==null?money(q.operation_total)+' EUR':'Pendiente de completar',true]]){const box=document.createElement('div');box.className='po-total'+(grand?' po-grand':'');const labelEl=document.createElement('span'),valueEl=document.createElement('strong');labelEl.textContent=label;valueEl.textContent=value;box.append(labelEl,valueEl);totals.append(box)}}
 new MutationObserver(render).observe($('proposal-cost-summary'),{childList:true,characterData:true,subtree:true});new MutationObserver(render).observe($('summary'),{childList:true,characterData:true,subtree:true});new MutationObserver(()=>{notice.textContent=$('notice').textContent}).observe($('notice'),{childList:true,characterData:true,subtree:true});$('supplier').addEventListener('change',render);render();
})();
'''
